from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain.agents import create_agent
from langchain.messages import AIMessage, HumanMessage

class FakeModel(GenericFakeChatModel):
    """Hace de LLM: imprime los mensajes que recibe y devuelve respuestas fijas."""
    def bind_tools(self, tools, **kwargs):
        return self
    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        print("El modelo recibe:", [type(m).__name__ for m in messages])
        return super()._generate(messages, stop=stop, run_manager=run_manager, **kwargs)

model = FakeModel(messages=iter([AIMessage("Luna City has domes and a spaceport.")]))

agent = create_agent(model=model, system_prompt="You are a science fiction writer.")

response = agent.invoke(
    {"messages": [HumanMessage(content="What's the capital of the Moon?"),
                  AIMessage(content="The capital of the Moon is Luna City."),
                  HumanMessage(content="Interesting, tell me more about Luna City")]}
)

print("Devuelve:", len(response["messages"]), "mensajes")
print(response["messages"][-1].content)

from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain.agents import create_agent
from langchain.messages import AIMessage, HumanMessage

class FakeModel(GenericFakeChatModel):
    """Hace de LLM: devuelve respuestas fijas (y las 'streamea' palabra por palabra)."""
    def bind_tools(self, tools, **kwargs):
        return self

model = FakeModel(messages=iter([AIMessage("Luna City sits under glass domes.")]))
agent = create_agent(model=model)

for token, metadata in agent.stream(
    {"messages": [HumanMessage(content="Tell me all about Luna City, the capital of the Moon")]},
    stream_mode="messages",
):
    if token.content:
        print(repr(token.content), "<- node:", metadata["langgraph_node"])
